import { randomUUID } from "node:crypto";
import { config } from "./config.mjs";
import { maskPhone, normaliseEmail, normalisePhone } from "./policy.mjs";

export const STATES = Object.freeze({ RINGING:"ringing", ROUTING:"routing", TRANSFERRING:"transferring", TRANSFERRED:"transferred", GREETING:"greeting", DISCOVERY:"discovery", QUALIFYING:"qualifying", CONFIRMING:"confirming", SAVING:"saving", CLOSING:"closing", ENDED:"ended" });
const TERMINAL = new Set([STATES.TRANSFERRED, STATES.ENDED]);
const TOPIC_LIMIT = 48;
const clip = (v, n) => { const s=String(v ?? "").replace(/\s+/g," ").trim(); return s.length<=n?s:`${s.slice(0,n-1).trimEnd()}…`; };

export class LeadCaptureFlow {
  constructor({ hours, catalog, store, transfer = null, hub = null, now = () => new Date(), options = {} }) {
    this.hours=hours; this.catalog=catalog; this.store=store; this.transfer=transfer; this.hub=hub; this.now=now;
    this.options={ callTimeBudgetMs: config.callTimeBudgetMs, maxNoInputs: 2, ...options };
    this.calls=new Map(); this.agents=new Map();
  }
  create({ callId=randomUUID(), fromPhone=null, incomingCallContext=null, sessionId=null, overflow=false, resourceAccountId=null, simulated=false } = {}) {
    const startedAt=this.now();
    const phone=normalisePhone(fromPhone);
    const call={ id:callId, fromPhone:phone, maskedPhone:maskPhone(phone), incomingCallContext, sessionId:sessionId??callId, resourceAccountId, overflow, simulated, callConnectionId:null, state:STATES.RINGING, startedAt:startedAt.toISOString(), answeredAt:null, endedAt:null, durationMs:null, outcome:null, draft:{ callbackPhone:phone, phoneConfirmed:Boolean(phone), emailConfirmed:false, notes:"" }, noInputs:0, transcript:[], savedLead:null, nonSales:null, routeDecision:null, pendingDispatch:null, dispatched:false };
    this.calls.set(call.id, call); this.store.startCall({ id:call.id, state:call.state, maskedPhone:call.maskedPhone, startedAt:call.startedAt, simulated }); this.#event(call,"system","call_created",call.maskedPhone); return call;
  }
  get(id){ return this.calls.get(id)??null; }
  registerAgent(id, handle){ this.agents.set(id, handle); }
  unregisterAgent(id){ this.agents.delete(id); }
  setCallConnection(id, ccid){ const c=this.get(id); if(c) c.callConnectionId=ccid; }
  routeIncoming(id){ const call=this.#require(id); this.#setState(call, STATES.ROUTING); const open=this.hours.isSalesOpen(this.now()); call.routeDecision={ open, holiday:this.hours.isHoliday(this.now()), overflow:call.overflow };
    if(open && !call.overflow) return this.#transferSales(call, { callTopic:"Sales inquiry", callContext:"In-hours caller connected directly to the sales queue." });
    this.#setState(call, STATES.GREETING); return this.answered(id);
  }
  answered(id){ const call=this.#require(id); call.answeredAt=this.now().toISOString(); this.#setState(call, STATES.DISCOVERY); const line="Thanks for calling Contoso Industrial Supply. I'm an automated assistant. Our sales team isn't available right now, but I can take your details and have the right person call you back. What are you looking for today?"; this.#say(call,line); return call; }
  lookupCatalog(id, query){ const call=this.#require(id); const matches=this.catalog.lookup(query); this.#event(call,"agent","lookup_catalog",query); return { ok:true, matches }; }
  updateFields(id, patch){ const call=this.#require(id); Object.assign(call.draft, sanitisePatch(patch)); this.#setState(call, STATES.QUALIFYING); this.#publish(call,"state",this.snapshot(id)); return { ok:true, draft:this.publicDraft(call) }; }
  saveLead(id, fields = {}, { partial=false } = {}) { const call=this.#require(id); if (TERMINAL.has(call.state)) return { ok:false, reason:"call_finished" }; this.updateFields(id, fields); this.#setState(call, STATES.SAVING); const result=this.store.saveLead(call.draft, { callId:id, partial }); if(!result.ok){ this.#event(call,"system","save_refused",result.reason); this.#setState(call, STATES.CONFIRMING); return result; } call.savedLead=result.lead; const publicResult={ ok:true, leadId:result.lead.id, duplicateOf:result.duplicateOf, slaPhrase:result.slaPhrase }; this.#event(call,"system",result.duplicateOf?"lead_merged":"lead_saved",result.lead.id); this.#setState(call, STATES.CLOSING); const first=call.draft.name?String(call.draft.name).split(/\s+/)[0]:"there"; this.#say(call,`Thanks, ${first}. Someone from our sales team will call you ${result.slaPhrase}.`); this.endCall(id, result.duplicateOf?"duplicate_merged":"lead_captured"); return publicResult; }
  classifyNonSales(id, kind, note="") { const call=this.#require(id); const allowed=new Set(["existing-customer","spam","emergency"]); const clean=allowed.has(kind)?kind:"existing-customer"; call.nonSales={ kind:clean, note }; this.store.saveNonSales({ callId:id, kind:clean, note }); const text= clean==="emergency" ? "If this is an emergency, please hang up and call emergency services now." : clean==="spam" ? "Thanks for calling. I'm going to end the call now." : `For order or service issues, please call support at ${this.hours.support.phone}. Support is available ${this.hours.support.hours}.`; this.#event(call,"system","non_sales",clean); this.#say(call,text); this.endCall(id, `non-sales:${clean}`); return { ok:true, kind:clean, text }; }
  noInput(id){ const call=this.#require(id); if(this.#budgetExpired(call)) return this.expire(id); call.noInputs+=1; this.#event(call,"caller","no_input",call.noInputs); if(call.noInputs>this.options.maxNoInputs) return this.saveLead(id,{ notes:appendNote(call.draft.notes,"Caller stopped responding; saved partial lead.") },{ partial:true }); this.#say(call,"Sorry, I didn't catch that. What product are you looking for, and how can our sales team reach you?"); return { ok:true, reprompt:true, attempt:call.noInputs }; }
  checkBudget(id){ const call=this.get(id); if(!call || TERMINAL.has(call.state)) return { ok:true }; if(this.#budgetExpired(call)) return this.expire(id); return { ok:true }; }
  expire(id){ const call=this.#require(id); this.#event(call,"system","budget_expired",this.options.callTimeBudgetMs); return this.saveLead(id,{ notes:appendNote(call.draft.notes,"Call time budget expired; saved partial lead.") },{ partial:true }); }
  endCall(id, outcome="agent_ended"){ const call=this.get(id); if(!call || TERMINAL.has(call.state)) return { ok:true }; call.outcome=outcome; call.endedAt=this.now().toISOString(); call.durationMs=new Date(call.endedAt)-new Date(call.startedAt); this.#setState(call, STATES.ENDED); this.store.updateCall(id,{ outcome, endedAt:call.endedAt, durationMs:call.durationMs }); return { ok:true }; }
  pushTranscript(id, role, text){ const call=this.get(id); if(!call||!text) return; call.transcript.push({ role, text, at:this.now().toISOString() }); this.store.recordTranscript(id, role, text); this.#publish(call,"transcript",{ role, text }); }
  handoffContext(call){ const product=call.draft.productInterest; return { sessionId:call.sessionId??call.id, callTopic:clip(product || "Sales inquiry", TOPIC_LIMIT), callContext:clip([call.draft.productInterest, call.draft.quantity?`quantity ${call.draft.quantity}`:"", call.draft.timeline].filter(Boolean).join(", ") || "Sales inquiry", 400), routeId:"sales", afterHours:false }; }
  async dispatchTransfer(id){ const call=this.#require(id); if(call.dispatched) return { ok:false, reason:"already_dispatched" }; call.dispatched=true; const context=this.handoffContext(call); if(!this.transfer){ this.#event(call,"system","transfer_simulated","sales"); this.#publish(call,"handoff",context); this.#finishTransfer(call,true); return { ok:true, simulated:true, context }; } await this.transfer(call,{ target:this.hours.salesQueue, context }); this.#event(call,"system","transfer_succeeded","sales"); this.#publish(call,"handoff",context); this.#finishTransfer(call,false); return { ok:true, context }; }
  publicDraft(call){ const { name, company, callbackPhone, phoneConfirmed, email, emailConfirmed, productInterest, quantity, timeline, role, location, notes }=call.draft; return { name, company, callbackPhone, phoneConfirmed, email, emailConfirmed, productInterest, quantity, timeline, role, location, notes }; }
  snapshot(id){ const call=this.get(id); if(!call) return null; return { id:call.id, state:call.state, maskedPhone:call.maskedPhone, routeDecision:call.routeDecision, draft:this.publicDraft(call), scoreBreakdown:call.savedLead?.scoreBreakdown ?? null, score:call.savedLead?.score ?? null, owner:call.savedLead?.owner ? { id:call.savedLead.owner.id, displayName:call.savedLead.owner.displayName } : null, savedLeadId:call.savedLead?.id ?? null, duplicateOf:call.savedLead?.duplicateOf ?? null, nonSales:call.nonSales, outcome:call.outcome, elapsedMs:(call.endedAt?new Date(call.endedAt):this.now())-new Date(call.startedAt), budgetMs:this.options.callTimeBudgetMs, transcript:call.transcript, handoff:call.state===STATES.TRANSFERRING||call.state===STATES.TRANSFERRED?this.handoffContext(call):null }; }
  #transferSales(call, contextSeed){ Object.assign(call.draft,{ productInterest:contextSeed.callTopic }); this.#setState(call, STATES.TRANSFERRING); this.#say(call,"Connecting you with our sales team now."); call.dispatchPromise=this.dispatchTransfer(call.id); return { ok:true, action:"transfer", routeId:"sales" }; }
  #finishTransfer(call, simulated){ call.outcome="transferred:sales"; call.endedAt=this.now().toISOString(); call.durationMs=new Date(call.endedAt)-new Date(call.startedAt); this.#setState(call, STATES.TRANSFERRED); this.store.updateCall(call.id,{ outcome:call.outcome, endedAt:call.endedAt, durationMs:call.durationMs, simulated }); }
  #budgetExpired(call){ return call.answeredAt && !TERMINAL.has(call.state) && this.now()-new Date(call.answeredAt) >= this.options.callTimeBudgetMs; }
  #require(id){ const c=this.calls.get(id); if(!c) throw new Error(`unknown call ${id}`); return c; }
  #setState(call,state){ if(call.state===state) return; const from=call.state; call.state=state; this.store.updateCall(call.id,{ state }); this.#event(call,"system","state",`${from} → ${state}`); this.#publish(call,"state",this.snapshot(call.id)); }
  #event(call,source,kind,detail){ this.store.recordEvent(call.id,source,kind,detail); this.#publish(call,"event",{ source, kind, detail, at:this.now().toISOString() }); }
  #say(call,text){ this.agents.get(call.id)?.instruct?.("", text); this.pushTranscript(call.id,"agent",text); }
  #publish(call,target,payload){ this.hub?.send?.(call.id,target,payload); }
}
function sanitisePatch(patch={}){ const out={...patch}; if(out.callbackPhone!==undefined) out.callbackPhone=normalisePhone(out.callbackPhone); if(out.email!==undefined) out.email=normaliseEmail(out.email) ?? String(out.email??"").trim().toLowerCase(); if(out.quantity!==undefined){ const m=String(out.quantity).replace(/,/g,"").match(/\d+/); out.quantity=m?Number(m[0]):null; } return out; }
function appendNote(existing,note){ return [existing,note].filter(Boolean).join(" "); }
